/// Execute the schema-declared `zeroclow_router.Chat` method after the mutation
/// engine has recorded the call. Provider/model selection remains owned by
/// the projected threetched schema; `ChatManager` only performs the resolved
/// upstream call.
pub(crate) async fn dispatch_schema_chat(
    chat_manager: &ChatManager,
    state: &TchedRouterState,
    input: ChatInput,
) -> anyhow::Result<ChatOutput> {
    let messages = if input.messages.is_empty() {
        if input.message.trim().is_empty() {
            return Err(anyhow!("zeroclow_router.Chat requires message or messages"));
        }
        vec![op_llm::ChatMessage {
            role: "user".to_string(),
            content: input.message,
            tool_calls: None,
            tool_call_id: None,
        }]
    } else {
        input
            .messages
            .into_iter()
            .map(|message| op_llm::ChatMessage {
                role: message.role,
                content: message.content,
                tool_calls: None,
                tool_call_id: None,
            })
            .collect()
    };

    let (route, response) =
