pub(crate) struct RuntimeSelection { … }

#[derive(Debug)]
pub(crate) struct NativeConfigMutation { … }

#[derive(Debug)]
pub(crate) struct NativeConfigObservation { … }

#[derive(Debug)]
pub(crate) struct CatalogBindingObservation { … }

impl NativeConfigObservation { … }

