struct HealthResponse {
    status: String,
}

#[derive(Debug, Deserialize)]
struct PropResponse {
    value: Value,
}

#[derive(Debug, Deserialize)]
struct ConfigListResponse {
    entries: Vec<ConfigListEntry>,
}

