1://! The plugin-owned upstream configuration contract for tched_router.
2://! The schema is captured from the verified threetched binary at every seal
3://! through the threetched plugin's pinned capture; nothing is imported or
4://! stored here. All section/method schemas derive from that one capture.
5:use serde_json::{Map, Value};
6:use std::collections::BTreeSet;
7:
8:pub fn document() -> &'static Value {
9:    super::threetched::config_schema()
10:        .expect("threetched config schema must be captured from the binary at seal")
11:}
12:
13:fn references(node: &Value, out: &mut BTreeSet<String>) {
14:    match node {
15:        Value::Object(map) => {
16:            if let Some(name) = map
17:                .get("$ref")
18:                .and_then(Value::as_str)
