    Provider {
        id: id.into(),
        ..Default::default()
    }
}

fn route(hint: &str, provider: &str, model: &str) -> ModelRoute {
    ModelRoute {
        hint: hint.into(),
        provider: provider.into(),
        model: model.into(),
        available: true,
        status: "available".into(),
        ..Default::default()
    }
}

