                    .as_object()
                    .cloned()
                    .context("native router fields must be an object")?;
                fields.insert("tools".into(), tools_value);
                Value::Object(fields)
            },
            schema_hash: pin.schema_hash.clone(),
        });
    }
    let methods = ZeroClawRouterLegacyMethods::new(
        documents.context("retained zeroclow_router method requires the configured durable owner")?,
    );
    let observed = ObservedZeroClawRouterState::from(&native);
    if matches!(method, "GetModelRoutes" | "ResolveRoute") {
        let receipt = methods.observe(method, args, &observed).await?;
